class CompetitionClock:
    def __init__(self, total_minutes):
        self.total_minutes = total_minutes
        self.phases = [
            ('eda', 0.15),
            ('baseline', 0.35),
            ('iteration', 0.80),
            ('ensemble', 0.95),
            ('final_submission', 1.00)
        ]

    def phase_status(self, elapsed_minutes):
        elapsed_frac = elapsed_minutes / self.total_minutes
        prev_end = 0.0
        for name, end_frac in self.phases:
            if elapsed_frac <= end_frac:
                phase_start_min = prev_end * self.total_minutes
                phase_end_min = end_frac * self.total_minutes
                remaining = phase_end_min - elapsed_minutes
                return {'phase': name, 'phase_minutes_remaining': remaining}
            prev_end = end_frac
        # Past all phases
        return {'phase': 'final_submission', 'phase_minutes_remaining': 0}

    def danger_alert(self, elapsed_minutes, has_submission=True):
        elapsed_frac = elapsed_minutes / self.total_minutes
        if elapsed_frac > 0.80 and not has_submission:
            return True
        return False

clock = CompetitionClock(300)
print(clock.phase_status(30))
print(clock.phase_status(100))
print(clock.danger_alert(250, has_submission=False))
